// 1. Recebe o JSON original vindo do nó MQTT
const dados = msg.payload;

// 2. Extrai e converte os valores estritamente para números (Float)
const campos = {
    sensor: "BME280",
    temperatura: parseFloat(dados.temperatura),
    pressao: parseFloat(dados.pressao),
    umidade: parseFloat(dados.umidade),
    timestamp: dados.timestamp * 1000
};

msg.payload = campos

return msg;

// ===================== Configuração =====================
const AGENTE = 'http://localhost:5000';   // endereço do agente MTConnect
const COUNT  = 1000;                      // máximo de sequências por requisição
// ========================================================

// Evita requisições sobrepostas caso o agente demore mais que o intervalo
const ocupado = flow.get('ifx_ocupado') || 0;
if (Date.now() - ocupado < 5000) return null;
flow.set('ifx_ocupado', Date.now());

// Leitura incremental: pede só o que chegou desde a última resposta (nextSequence)
const proximo = flow.get('ifx_proximo');
msg.url = AGENTE + '/sample?count=' + COUNT + (proximo != null ? '&from=' + proximo : '');
msg.headers = { Accept: 'application/xml' };
msg.requestTimeout = 4000;
msg.ifx_from = proximo;
return msg;

