func:
// =============================== Configuração ===============================
const DISPOSITIVO     = 'SensorVibracao'; // nome do device no agente MTConnect
const MEDICAO         = 'vibracao';       // tabela das amostras no InfluxDB
const MEDICAO_RMS     = 'vibracao_rms';   // tabela com RMS e pico de cada janela
const RECUPERAR       = 1800;             // ao conectar, quantas observações antigas buscar no agente
                                          // (3 por segundo → 1800 ≈ 10 min; 0 = só dados novos)
const PONTOS_POR_LOTE = 5000;             // pontos por write (~0,5 MB; o InfluxDB recusa acima de 10 MB)
const ALERTA_S        = 30;               // status amarelo se o sensor ficar esse tempo sem enviar
// ============================================================================

flow.set('ifx_ocupado', 0);   // a resposta chegou: libera o nó que faz as requisições ao agente
const status = (cor, texto) =>
    node.status({ fill: cor, shape: 'dot', text: texto + ' · ' + new Date().toLocaleTimeString('pt-BR') });

// 1) A resposta do agente é válida?
const raiz = msg.payload?.MTConnectStreams;
if (!raiz) {
    flow.set('ifx_instancia', null);   // na próxima resposta válida, sincroniza de novo
    flow.set('ifx_proximo', null);
    status('yellow', 'resposta inválida do agente — ressincronizando');
    return null;
}
const cab   = raiz.Header?.[0]?.$ ?? {};
const first = Number(cab.firstSequence);   // observação mais antiga no buffer do agente
const last  = Number(cab.lastSequence);    // observação mais nova
const next  = Number(cab.nextSequence);    // de onde a próxima leitura deve continuar

// 2) Primeira resposta, ou o agente reiniciou: escolhe de onde começar e pede de novo
if (cab.instanceId !== flow.get('ifx_instancia')) {
    flow.set('ifx_instancia', cab.instanceId);
    flow.set('ifx_proximo', Math.max(first, last + 1 - RECUPERAR));
    context.set('ultimaAmostra', Date.now());
    status('blue', 'conectado ao agente — sincronizando');
    return [null, { continuar: true }];
}
flow.set('ifx_proximo', next);   // a próxima requisição continua daqui

// 3) Transforma cada amostra em um ponto do InfluxDB
const pontos   = [];   // amostras          → tabela MEDICAO
const resumos  = [];   // RMS e pico/janela → tabela MEDICAO_RMS
for (const streams of raiz.Streams ?? []) {
    for (const device of streams.DeviceStream ?? []) {
        if (device.$?.name !== DISPOSITIVO) continue;
        const tags = { dispositivo: device.$.name, uuid: device.$.uuid };
        for (const componente of device.ComponentStream ?? []) {
            for (const samples of componente.Samples ?? []) {
                for (const [tipo, itens] of Object.entries(samples)) {
                    if (tipo === '$') continue;              // '$' são atributos, não amostras
                    for (const item of itens) {
                        const atr   = item.$ ?? {};
                        const sinal = atr.dataItemId;        // acc_x, acc_y ou acc_z
                        const texto = (item._ ?? '').trim(); // "v1 v2 v3 ... v256"
                        const t     = Date.parse(atr.timestamp);
                        if (!sinal || !texto || isNaN(t)) continue;
                        const valores = texto.split(/\s+/).map(Number);
                        if (valores.some(isNaN)) continue;   // ex.: UNAVAILABLE

                        // O firmware não manda horário, então o agente marca a chegada da série,
                        // logo depois da última amostra. Cada amostra anterior fica 1/taxa mais cedo.
                        const passo = atr.sampleRate ? 1000 / Number(atr.sampleRate) : 0;   // ms
                        valores.forEach((v, i) => pontos.push({
                            measurement: MEDICAO,
                            tags,
                            fields: { [sinal]: v },
                            timestamp: new Date(t - (valores.length - 1 - i) * passo)
                        }));

                        // Resumo da janela, sem a média (a gravidade fica toda na média)
                        if (valores.length > 1) {
                            const media   = valores.reduce((s, v) => s + v, 0) / valores.length;
                            const desvios = valores.map(v => v - media);
                            resumos.push({
                                measurement: MEDICAO_RMS,
                                tags,
                                fields: {
                                    [sinal + '_rms']:  Math.sqrt(desvios.reduce((s, d) => s + d * d, 0) / desvios.length),
                                    [sinal + '_pico']: Math.max(...desvios.map(Math.abs))
                                },
                                timestamp: new Date(t)
                            });
                        }
                    }
                }
            }
        }
    }
}

// 4) Divide em lotes: cada lote vira um write separado, sempre bem abaixo dos 10 MB
const lotes = [];
for (const lista of [pontos, resumos]) {
    for (let i = 0; i < lista.length; i += PONTOS_POR_LOTE) {
        const parte = lista.slice(i, i + PONTOS_POR_LOTE);
        lotes.push({ measurement: parte[0].measurement, payload: parte });
    }
}

// 5) Status no editor, com alerta se o sensor parou de mandar dados
if (pontos.length) context.set('ultimaAmostra', Date.now());
const parado = Math.round((Date.now() - context.get('ultimaAmostra')) / 1000);
if (parado >= ALERTA_S) status('yellow', `⚠️ sem amostras há ${parado} s`);
else status('green', `${pontos.length} pontos em ${lotes.length} lote(s) · seq ${next - 1}`);

// 6) Ainda há dados no buffer do agente (e a leitura avançou)? Pede a próxima parte já
const temMais = next <= last && (msg.ifx_from == null || next > msg.ifx_from);
return [lotes.length ? lotes : null, temMais ? { continuar: true } : null];

// Trata falhas de comunicação (sem conexão, timeout, HTTP != 200) e erros de parsing
flow.set('ifx_ocupado', 0);
let texto;

if (msg.error) {
    texto = 'erro ao interpretar a resposta: ' + msg.error.message;
} else if (typeof msg.statusCode === 'number') {
    // o agente respondeu com erro (ex.: OUT_OF_RANGE quando o buffer foi sobrescrito): ressincroniza
    flow.set('ifx_proximo', null);
    flow.set('ifx_instancia', null);
    const m = String(msg.payload || '').match(/errorCode="([^"]+)"/);
    texto = 'agente respondeu HTTP ' + msg.statusCode + (m ? ' (' + m[1] + ')' : '') + ' — ressincronizando';
} else {
    texto = 'sem conexão com o agente MTConnect (' + (msg.statusCode || msg.payload || 'erro') + ')';
}

node.status({ fill: 'red', shape: 'ring', text: texto + ' · ' + new Date().toLocaleTimeString('pt-BR') });
return null;
